<script lang="ts">
 import {onMount} from 'svelte';
 import {locale,t} from '$lib/i18n';
 import {goto} from '$app/navigation';
 import {base} from '$app/paths';
 import * as Sidebar from '$lib/components/ui/sidebar';
 import AddMediaCard from '$lib/components/add-media-card.svelte';
 let {kind}:{kind:'movie'|'tv'}=$props();
 let mode=$state('trending'),window=$state('week'),region=$state('DE'),provider=$state(''),company=$state(''),genre=$state(''),companyQuery=$state(''),minVotes=$state('100');
 let pageNumber=$state(1),busy=$state(false),optionsBusy=$state(false),companyBusy=$state(false),error=$state(''),optionsError=$state(''),companyError=$state('');
 let results=$state<any[]>([]),providers=$state<any[]>([]),genres=$state<any[]>([]),regions=$state<any[]>([]),companies=$state<any[]>([]);
 let totalPages=$state(1),totalResults=$state(0),loaded=$state(false),hideExisting=$state(false);let requestId=0;
 const lists=[{id:'trending',name:'Trending'},{id:'popular',name:'Popular'},{id:'top_rated',name:'Top rated'},{id:'recent',name:'Recently released'}];
 let displayed=$derived(hideExisting?results.filter(r=>!r.added):results);
 let quickProviders=$derived(providers.filter(p=>/^(netflix|amazon prime video|disney plus|apple tv\+|paramount plus)$/i.test(p.name)).slice(0,6));
 function values(page=1){const p=new URLSearchParams({mode,window,page:String(page),region,language:$locale,min_votes:minVotes});if(provider)p.set('provider_id',provider);if(company)p.set('company_id',company);if(genre)p.set('genre_id',genre);return p;}
 async function read(response:Response){const data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:t($locale,'Discovery could not be loaded.'));return data;}
 async function load(page=1,updateUrl=true){const id=++requestId;busy=true;error='';pageNumber=page;try{const data=await read(await fetch('/api/v1/discover/'+kind+'?'+values(page)));if(id!==requestId)return;results=data.results;totalPages=data.total_pages;totalResults=data.total_results;loaded=true;if(updateUrl){const query=values(page);if(companyQuery)query.set('company_name',companyQuery);await goto('?'+query,{replaceState:true,noScroll:true,keepFocus:true});}}catch(e){if(id===requestId){error=(e as Error).message;results=[];loaded=false;}}finally{if(id===requestId)busy=false;}}
 async function loadOptions(){optionsBusy=true;optionsError='';try{const data=await read(await fetch('/api/v1/discover/'+kind+'/options?'+new URLSearchParams({region,language:$locale})));providers=data.providers;genres=data.genres;regions=data.regions;}catch(e){optionsError=(e as Error).message;}finally{optionsBusy=false;}}
 async function findCompanies(){if(companyQuery.trim().length<2)return;companyBusy=true;companyError='';try{companies=await read(await fetch('/api/v1/discover/companies?'+new URLSearchParams({query:companyQuery.trim()})));if(!companies.length)companyError=t($locale,'No studios found.');}catch(e){companyError=(e as Error).message;}finally{companyBusy=false;}}
 function changeFilter(){filtered();void load(1);}
 function filtered(){if((provider||company||genre)&&mode==='trending')mode='popular';}
 async function changeRegion(){provider='';await loadOptions();void load(1);}
 function chooseList(value:string){mode=value;if(mode==='trending'){provider='';company='';genre='';}void load(1);}
 function reset(){mode='trending';window='week';provider='';company='';genre='';companyQuery='';companies=[];minVotes='100';hideExisting=false;void load(1);}
 onMount(()=>{const q=new URLSearchParams(location.search);const selected=q.get('mode');if(lists.some(l=>l.id===selected))mode=selected!;window=q.get('window')==='day'?'day':'week';region=/^[A-Z]{2}$/.test(q.get('region')??'')?q.get('region')!:'DE';provider=q.get('provider_id')??'';company=q.get('company_id')??'';genre=q.get('genre_id')??'';companyQuery=q.get('company_name')??'';if(company)companies=[{id:Number(company),name:companyQuery||'TMDB #'+company}];const votes=q.get('min_votes');if(votes&&['0','50','100','500','1000'].includes(votes))minVotes=votes;filtered();void loadOptions();void load(Math.max(1,Math.min(500,Number(q.get('page'))||1)),false);return()=>{requestId++;};});
</script>
<svelte:head><title>{t($locale,kind==='tv'?'Discover series':'Discover movies')} – MediaManager</title></svelte:head>
<header class="flex h-16 shrink-0 items-center gap-3 px-4"><Sidebar.Trigger/><a href={base+'/dashboard'} class="text-sm text-muted-foreground">MediaManager</a><span class="text-muted-foreground">/</span><span class="text-sm">{t($locale,kind==='tv'?'Series':'Movies')}</span><span class="text-muted-foreground">/</span><span class="text-sm font-medium">{t($locale,'Discover')}</span></header>
<main class="mx-auto w-full min-w-0 max-w-[96rem] space-y-5 p-4">
 <section class="rounded-2xl border bg-gradient-to-br from-primary/10 via-card to-card p-5 sm:p-7"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs font-semibold uppercase tracking-widest text-primary">TMDB · {t($locale,'Discovery')}</p><h1 class="mt-2 text-3xl font-bold tracking-tight">{t($locale,kind==='tv'?'Discover series':'Discover movies')}</h1></div><a class="rounded-lg border bg-background px-4 py-2 text-sm" href={base+'/dashboard/'+(kind==='tv'?'tv':'movies')}>{t($locale,'Open library')}</a></div><p class="mt-3 max-w-3xl text-sm text-muted-foreground">{t($locale,'Browse current trends or explore by streaming provider, studio and genre. Existing library titles stay visible.')}</p></section>
 <nav aria-label={t($locale,'Discovery lists')} class="flex flex-wrap gap-2">{#each lists as list}<button type="button" aria-pressed={mode===list.id} class="rounded-xl border px-4 py-2.5 text-sm font-medium aria-pressed:bg-primary aria-pressed:text-primary-foreground disabled:opacity-50" disabled={busy} onclick={()=>chooseList(list.id)}>{t($locale,list.name)}</button>{/each}</nav>
 <section class="space-y-4 rounded-2xl border bg-card p-4 sm:p-5" aria-label={t($locale,'Discovery filters')}>
  <div class="grid min-w-0 gap-4 sm:grid-cols-2 lg:grid-cols-4">
   <label class="min-w-0 text-sm font-medium">{t($locale,'Streaming region')}<select class="mt-2 block w-full min-w-0 rounded-lg border bg-background p-2.5" bind:value={region} onchange={changeRegion} disabled={optionsBusy}>{#if !regions.length}<option value={region}>{region}</option>{/if}{#each regions as r}<option value={r.id}>{r.name} ({r.id})</option>{/each}</select></label>
   <label class="min-w-0 text-sm font-medium">{t($locale,'Streaming provider')}<select class="mt-2 block w-full min-w-0 rounded-lg border bg-background p-2.5" bind:value={provider} onchange={changeFilter} disabled={optionsBusy}><option value="">{t($locale,'All providers')}</option>{#each providers as p}<option value={String(p.id)}>{p.name}</option>{/each}</select></label>
   <label class="min-w-0 text-sm font-medium">{t($locale,'Genre')}<select class="mt-2 block w-full min-w-0 rounded-lg border bg-background p-2.5" bind:value={genre} onchange={changeFilter} disabled={optionsBusy}><option value="">{t($locale,'All genres')}</option>{#each genres as g}<option value={String(g.id)}>{g.name}</option>{/each}</select></label>
   <label class="min-w-0 text-sm font-medium">{t($locale,mode==='trending'?'Trend period':'Minimum votes')}{#if mode==='trending'}<select class="mt-2 block w-full rounded-lg border bg-background p-2.5" bind:value={window} onchange={()=>load(1)}><option value="week">{t($locale,'This week')}</option><option value="day">{t($locale,'Today')}</option></select>{:else}<select class="mt-2 block w-full rounded-lg border bg-background p-2.5" bind:value={minVotes} onchange={()=>load(1)}>{#each ['0','50','100','500','1000'] as count}<option value={count}>{count==='0'?t($locale,'Any number of votes'):count+'+'}</option>{/each}</select>{/if}</label>
  </div>
  {#if quickProviders.length}<div class="flex flex-wrap gap-2" aria-label={t($locale,'Popular providers')}>{#each quickProviders as p}<button type="button" aria-pressed={provider===String(p.id)} class="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm aria-pressed:border-primary aria-pressed:bg-primary/10" onclick={()=>{provider=provider===String(p.id)?'':String(p.id);changeFilter();}}>{#if p.logo}<img src={p.logo} alt="" class="h-6 w-6 rounded object-contain"/>{/if}{p.name}</button>{/each}</div>{/if}
  <div class="grid min-w-0 gap-3 md:grid-cols-2"><div class="min-w-0"><label class="block text-sm font-medium" for={'studio-'+kind}>{t($locale,'Studio / production company')}</label><div class="mt-2 flex min-w-0 gap-2"><input id={'studio-'+kind} class="w-full min-w-0 flex-1 rounded-lg border bg-background p-2.5 text-sm" bind:value={companyQuery} placeholder={t($locale,'e.g. Warner, A24, BBC…')} onkeydown={e=>{if(e.key==='Enter'){e.preventDefault();void findCompanies();}}}/><button type="button" class="shrink-0 rounded-lg border px-3 text-sm disabled:opacity-50" disabled={companyBusy||companyQuery.trim().length<2} onclick={findCompanies}>{t($locale,'Search studio')}</button></div></div><label class="min-w-0 text-sm font-medium">{t($locale,'Selected studio')}<select class="mt-2 block w-full min-w-0 rounded-lg border bg-background p-2.5 text-sm" bind:value={company} onchange={changeFilter}><option value="">{t($locale,'All studios')}</option>{#each companies as c}<option value={String(c.id)}>{c.name}{c.country?' · '+c.country:''} · #{c.id}</option>{/each}</select></label></div>
  {#if companyError}<p role="status" class="text-sm text-muted-foreground">{t($locale,companyError)}</p>{/if}
  <div class="flex flex-wrap items-center justify-between gap-3"><label class="flex items-center gap-2 text-sm"><input type="checkbox" bind:checked={hideExisting}/>{t($locale,'Hide titles already in library')}</label><div class="flex gap-2"><button class="rounded-lg border px-4 py-2 text-sm" onclick={reset}>{t($locale,'Reset filters')}</button><button class="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground disabled:opacity-50" disabled={busy} onclick={()=>load(1)}>{t($locale,busy?'Loading…':'Apply filters')}</button></div></div>
  <p class="text-xs text-muted-foreground">{t($locale,mode==='trending'?'Trends are worldwide. Choosing provider, studio or genre switches to the filtered Popular catalogue.':'Provider results use subscription availability in the selected region. Recently released covers the past year; minimum votes reduce obscure one-vote results.')}</p>
  {#if optionsError}<p role="alert" class="text-sm text-destructive">{t($locale,optionsError)}</p>{/if}
 </section>
 {#if error}<div role="alert" class="rounded-xl border border-destructive p-4 text-sm text-destructive">{t($locale,error)}</div>{/if}
 <div aria-live="polite" class="flex flex-wrap items-center justify-between gap-3"><p class="text-sm text-muted-foreground">{busy?t($locale,'Loading…'):mode==='trending'?t($locale,window==='week'?'TMDB trends this week':'TMDB trends today'):totalResults.toLocaleString($locale)+' '+t($locale,'results on TMDB')}{#if loaded} · {displayed.length} {t($locale,'titles on this page')}{/if}</p>{#if totalPages>1}<div class="flex items-center gap-2"><button class="rounded-lg border px-3 py-2 text-sm disabled:opacity-40" disabled={busy||pageNumber<=1} onclick={()=>load(pageNumber-1)}>{t($locale,'Previous')}</button><span class="text-sm">{pageNumber} / {totalPages}</span><button class="rounded-lg border px-3 py-2 text-sm disabled:opacity-40" disabled={busy||pageNumber>=totalPages} onclick={()=>load(pageNumber+1)}>{t($locale,'Next')}</button></div>{/if}</div>
 <section aria-label={t($locale,'Discovery results')} class="grid min-w-0 grid-cols-2 items-stretch gap-3 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">{#each displayed as result (result.external_id)}<div class="h-full min-w-0"><AddMediaCard {result} isShow={kind==='tv'}/></div>{:else}{#if loaded&&!busy}<p class="col-span-full rounded-xl border p-6 text-center text-muted-foreground">{t($locale,'No titles match this selection. Try fewer filters or show existing titles.')}</p>{/if}{/each}</section>
 <footer class="text-xs text-muted-foreground">{t($locale,'Metadata:')} <a class="underline" href="https://www.themoviedb.org/" target="_blank" rel="noreferrer">TMDB</a> · {t($locale,'Streaming availability:')} <a class="underline" href="https://www.justwatch.com/" target="_blank" rel="noreferrer">JustWatch</a>. {t($locale,'This product uses the TMDB API but is not endorsed or certified by TMDB.')}</footer>
</main>
